const cors = require('cors');
const app = express();

// 1. Enable CORS for all incoming requests (Local development)
app.use(cors());

// 2. Or restrict to specific origins:
// app.use(cors({
//   origin: ['http://localhost:3000', 'https://yourdomain.com'],
